ctive']?'danger':'success'; ?> btn-sm btn-toggle-plan" data-id="<?= (int)$p['id']; ?>"><i class="fa-solid fa-<?= $p['is_active']?'pause':'play'; ?>"></i><?= $p['is_active']?'Deactivate':'Activate'; ?></button><?php elseif($eligible): ?><button class="btn btn-primary btn-sm btn-apply" data-id="<?= (int)$p['id']; ?>" data-name="<?= htmlspecialchars($p['name']); ?>" data-max="<?= htmlspecialchars($p['max_amount']??''); ?>" data-bs-toggle="modal" data-bs-target="#applyModal"><i class="fa-solid fa-paper-plane"></i>Apply</button><?php endif; ?><button class="btn btn-outline-secondary btn-sm" onclick='Swal.fire({title:<?= json_encode($p['name']); ?>,html:<?= json_encode("<p>".htmlspecialchars($p['description']??'')."</p><strong>Eligibility</strong><p>".htmlspecialchars($p['eligibility_rules']??'Not specified')."</p><strong>Required Documents</strong><p>".htmlspecialchars($p['required_documents']??'Supporting document')."</p>"); ?>})'><i class="fa-regular fa-eye"></i>Details</button></footer></article></div><?php endforeach; ?></div>
