btn-primary btn-sm btn-resubmit" data-claim='<?= htmlspecialchars(json_encode($c),ENT_QUOTES); ?>' data-bs-toggle="modal" data-bs-target="#applyModal">Resubmit</button><?php else: ?><span class="text-secondary small">Tracking</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
