/label><div class="benefit-option-grid" id="planStatuses"><?php foreach(['Active','Probationary','Resigned','Terminated','Retired'] as $status): ?><label class="benefit-option"><input type="checkbox" name="eligible_employment_statuses[]" value="<?= $status; ?>"><span><i class="fa-solid fa-check"></i><?= $status; ?></span></label><?php endforeach; ?></div><small class="form-text">Select all eligible statuses.</small></div><div class="col-md-4"><label class="form-label">Departments</label><div class="benefit-option-grid" id="planDepartments"><?php foreach($departments as $d): ?><label class="benefit-option"><input type="checkbox" name="eligible_department_ids[]" value="<?= (int)$d['id']; ?>"><span><i class="fa-solid fa-check"></i><?= htmlspecialchars($d['name']); ?></span></label><?php endforeach; ?></div><small class="form-text">Leave empty to allow every department.</small></div><label><input type="checkbox" name="is_active" id="planActive" value="1" checked> Active and available</label></div><div class="modal-footer"><button class="btn btn-primary">Save Benefit</button></div></form></div></div>
