<script>$(function(){
 const send=(url,form)=>$.ajax({url,type:'POST',data:new FormData(form),contentType:false,processData:false,dataType:'json'}).done(r=>{if(r.status==='success'){showToast('success',r.message);setTimeout(()=>location.reload(),700)}else showErrorDialog(r.message||'The request could not be completed.')}).fail(x=>showErrorDialog(x.responseJSON?.message||'The request could not be completed.'));
 <?php if(!$is_admin): ?>
 $('.btn-apply').on('click',function(){$('#applicationForm')[0].reset();$('#applicationId').val('');$('#applicationBenefit').val(this.dataset.id);$('#applicationBenefitName').text(this.dataset.name);$('#applicationTitle').text('Apply for Benefit')});
 $('.btn-resubmit').on('click',function(){const c=$(this).data('claim');$('#applicationForm')[0].reset();$('#applicationId').val(c.id);$('#applicationBenefit').val(c.benefit_id);$('#applicationType').val(c.claim_type);$('#applicationAmount').val(c.amount);$('#applicationReference').val(c.receipt_number);$('#applicationNotes').val(c.application_notes);$('#applicationBenefitName').text(c.benefit_name);$('#applicationTitle').text('Resubmit Returned Application')});
 $('#applicationForm').on('submit',function(e){e.preventDefault();send($('#applicationId').val()?'index.php?page=benefits_resubmit':'index.php?page=benefits_submit_claim',this)});
 <?php else: ?>
 $('.btn-new-plan').on('click',()=>{$('#planForm')[0].reset();$('#planId').val('');$('#planTitle').text('Create Benefit')});
 $('.btn-edit-plan').on('click',function(){
  const p=$(this).data('plan'),statuses=(p.eligible_employment_statuses||'').split(','),departments=(p.eligible_department_ids||'').split(',');
  $('#planId').val(p.id);$('#planTitle').text('Edit Benefit');$('#planName').val(p.name);$('#planType').val(p.type);$('#planDescription').val(p.description);$('#planRules').val(p.eligibility_rules);$('#planDocuments').val(p.required_documents);$('#planMax').val(p.max_amount);$('#planStart').val(p.application_start);$('#planEnd').val(p.application_end);$('#planTenure').val(p.minimum_tenure_months);
  $('#planStatuses input').each(function(){this.checked=statuses.includes(this.value)});
  $('#planDepartments input').each(function(){this.checked=departments.includes(this.value)});
  $('#planActive').prop('checked',p.is_active==1)
 });
 $('#planForm').on('submit',function(e){e.preventDefault();send($('#planId').val()?'index.php?page=benefits_plan_update':'index.php?page=benefits_plan_store',this)});
 $('.btn-toggle-plan').on('click',function(){$.post('index.php?page=benefits_plan_toggle',{id:this.dataset.id,csrf_token:'<?= $csrf; ?>'},r=>{showToast(r.status,r.message);if(r.status==='success')setTimeout(()=>location.reload(),600)},'json')});
 $('.btn-review').on('click',function(){const c=$(this).data('claim');$('#reviewId').val(c.id);$('#reviewContext').text(c.first_name+' '+c.last_name+' — '+c.benefit_name+' ('+c.status+')')});
 $('#reviewForm').on('submit',function(e){e.preventDefault();const status=$('#reviewStatus').val(),remarks=$(this).find('[name="admin_remarks"]').val().trim();if(['Returned','Rejected'].includes(status)&&!remarks){showErrorDialog('Admin remarks are required when returning or rejecting an application.','Remarks required');return;}send('index.php?page=admin_update_claim_status',this)});
 <?php endif; ?>
 if($.fn.DataTable.isDataTable('#benefitApplicationsTable'))$('#benefitStatusFilter').on('change',function(){$('#benefitApplicationsTable').DataTable().search(this.value).draw()})
});</script>
